$Deployment_Tools_DDL = (Invoke-WebRequest -UseBasicParsing -Uri 'https://go.microsoft.com/fwlink/?linkid=2196127' -MaximumRedirection 0 -ErrorAction SilentlyContinue).Headers.Location
$Deployment_Tools_Filename = [IO.Path]::GetFileName(([URI]$Deployment_Tools_DDL).AbsolutePath)
$Deployment_Tools_SavePath = [IO.Path]::Combine($env:TEMP, $Deployment_Tools_Filename)
[Console]::BackgroundColor = 'Black'; [Console]::ForegroundColor = 'Green'; [Console]::Write('Downloading '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'Windows Deployment Tools'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' from '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$Deployment_Tools_DDL'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' to '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$Deployment_Tools_SavePath'"); [Console]::ResetColor(); [Console]::WriteLine()
(New-Object System.Net.WebClient).DownloadFile($Deployment_Tools_DDL, $Deployment_Tools_SavePath)

$Deployment_Tools_Argument = '/quiet /features OptionId.DeploymentTools'
[Console]::BackgroundColor = 'Black'; [Console]::ForegroundColor = 'Green'; [Console]::Write('Installing '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'Windows Deployment Tools'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' from '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$Deployment_Tools_SavePath'"); [Console]::ForegroundColor = 'Green'; [Console]::Write(' with '); [Console]::ForegroundColor = 'Yellow'; [Console]::Write("'$Deployment_Tools_Argument'"); [Console]::ResetColor(); [Console]::WriteLine()
Start-Process $Deployment_Tools_SavePath -ArgumentList $Deployment_Tools_Argument